window.INSTRUMENTS=[{slug:"erhu",code:"ERHU.001",name:"二胡",nameEn:"ERHU",category:"拉弦",line:"胡琴之宗 · 中国小提琴",altName:"南胡 · 嗡子",image:"assets/erhu.png",music:"assets/audio/erhu.mp3",imageAlt:"现代二胡，六角琴筒、琴杆与琴弓",summary:"乐器 01 / 06 · 胡琴之宗 · “中国小提琴”",intro:"又称南胡、嗡子，是胡琴家族中最具代表性的拉弦乐器。它历史悠久，音色柔美深沉、如泣如诉，也能表现热烈奔放的情绪，常被称为“中国小提琴”。",history:"二胡的前身可追溯到唐代的奚琴，宋代称嵇琴，元代以后逐渐发展为胡琴。明清时期，二胡广泛用于戏曲、说唱和民间音乐伴奏。近代刘天华将二胡带入高等音乐教育，创作了十大二胡名曲，并对其进行改良；华彦钧（阿炳）则以《二泉映月》等作品让二胡走向世界。",construction:"二胡主要由琴筒、琴皮、琴杆、琴轴、千斤、琴弦、琴码、音垫和琴弓组成。琴筒是共鸣箱，多为圆形、六角形或八角形，一端蒙蟒皮，蟒皮对音色影响极大。琴杆上装有两个琴轴，张两根弦，内弦、外弦。千斤用于固定有效弦长，琴码传导振动，音垫用于控制噪音和音色。琴弓的马尾夹在两根弦之间，摩擦发声。",schools:"近代二胡形成多个流派，如无锡派、蒋派、秦派、粤派、川派、河南派等。无锡派以刘天华、华彦钧为代表，风格深沉细腻；蒋派以蒋风之为代表，典雅含蓄；秦派以鲁日融为代表，高亢激越，融入秦腔元素；粤派以吕文成为代表，明亮华丽，富有广东音乐韵味。",featuredMusic:"赛马（二胡版）",zones:[{key:"history",zone:"上",anchor:"琴头 · 琴轴",x:.5,y:.2},{key:"construction",zone:"中",anchor:"琴杆 · 千斤 · 琴弦",x:.52,y:.5},{key:"schools",zone:"下",anchor:"琴筒 · 琴皮 · 琴弓",x:.5,y:.78}]},{slug:"guzheng",code:"GUZHENG.002",name:"古筝",nameEn:"GUZHENG",category:"弹拨",line:"众乐之王 · 东方钢琴",altName:"秦筝 · 汉筝",image:"assets/guzheng.png",music:"assets/audio/guzheng.mp3",featuredMusic:"渔舟唱晚",imageAlt:"古筝，首尾深色镶嵌、面板多弦与筝码",summary:"乐器 02 / 06 · 众乐之王 · “东方钢琴”",intro:"又称秦筝、汉筝，是中国传统弹拨乐器中最具代表性的乐器之一。它历史悠久，音色清亮悠扬、刚柔并济，既能表现典雅古朴的意境，也能演奏热烈奔放的现代作品，因此常被称为“众乐之王”，也有“东方钢琴”之誉。",history:"古筝距今已有两千五百多年历史。春秋战国时期，筝已在秦地（今陕西一带）流行，故称“秦筝”。秦汉以后逐渐传入中原并广泛发展；唐宋时期常用于宫廷燕乐和民间音乐；明清以后形成多种地方流派。历史上筝的弦数并不固定，曾有五弦、十二弦、十三弦、十六弦等，现代通用为二十一弦。",construction:"古筝为长方形木质共鸣箱，主要由面板、底板、侧板、前岳山、后岳山、筝码、琴弦和调音盒等组成。面板多用桐木，底板常用梓木，筝码又称“雁柱”，可移动，用来调节音高和音准。现代琴弦多为钢丝尼龙缠弦，音色明亮且稳定。",schools:"古筝在各地形成了不同流派，如山东筝、河南筝、潮州筝、客家筝、浙江筝、陕西筝、福建筝等。山东筝刚健明快，河南筝高亢粗犷，潮州筝细腻婉转，客家筝古朴典雅，浙江筝清丽流畅，陕西筝则多悲壮激越之气。",zones:[{key:"history",zone:"上",anchor:"首端 · 岳山",x:.82,y:.5},{key:"construction",zone:"中",anchor:"面板 · 筝码（雁柱）",x:.5,y:.5},{key:"schools",zone:"下",anchor:"尾端 · 调音盒",x:.18,y:.5}]},{slug:"pipa",code:"PIPA.003",name:"琵琶",nameEn:"PIPA",category:"弹拨",line:"弹拨乐器之王",altName:"批把 · 枇杷",image:"assets/pipa.png",music:"assets/audio/pipa.mp3",featuredMusic:"琵琶语（琵琶版）",imageAlt:"琵琶，梨形琴身、琴头弦轴与相品",summary:"乐器 03 / 06 · 弹拨乐器之王",intro:"又称批把、枇杷，是中国传统弹拨乐器中最具代表性的乐器之一。它历史悠久，音色清脆明亮、富有颗粒感，既能表现文曲的细腻委婉，也能演奏武曲的激烈磅礴，因此常被称为“弹拨乐器之王”。",history:"琵琶二字最早见于汉代，最初是多种弹拨乐器的总称。秦代有弦鼗，汉代有秦琵琶、汉琵琶。南北朝时期，曲项琵琶从西域经丝绸之路传入，梨形音箱，四弦四柱，横抱，用拨子演奏。唐代是琵琶鼎盛期，成为宫廷燕乐和民间音乐的重要乐器，并逐渐由横抱改为竖抱，由拨子改为手指弹奏。宋元明清，形制逐步定型为四弦多相多品的现代琵琶。近代刘天华、华彦钧等音乐家对琵琶创作和演奏也有重要贡献。",construction:"琵琶主要由琴头、琴颈、琴身、面板、背板、相、品、弦轴、琴弦和缚弦等组成。音箱呈梨形，面板多用桐木，背板多用红木、紫檀等硬木。琴颈和面板上设有相和品，用于按音。现代琵琶通常为四弦，六相二十四品或二十五品，音位齐全，便于转调。",schools:"近代琵琶形成五大流派：无锡派、平湖派、浦东派、崇明派、汪派。无锡派以华秋苹为代表，风格清丽；平湖派以李芳园为代表，文雅细腻；浦东派以鞠士林、沈浩初为代表，气势雄浑；崇明派以沈肇州为代表，古朴典雅；汪派以汪昱庭为代表，刚柔并济。各派在曲目、技法和审美上各有特色。",zones:[{key:"history",zone:"上",anchor:"琴头 · 琴颈 · 相",x:.5,y:.16},{key:"construction",zone:"中",anchor:"面板 · 品 · 琴弦",x:.5,y:.5},{key:"schools",zone:"下",anchor:"缚弦 · 琴腹",x:.5,y:.84}]},{slug:"dizi",code:"DIZI.004",name:"笛子",nameEn:"DIZI",category:"吹管",line:"民乐之魂",altName:"竹笛",image:"assets/dizi.png",music:"assets/audio/dizi.mp3",imageAlt:"竹笛，管身吹孔、膜孔与按音孔",summary:"乐器 04 / 06 · 民乐之魂",intro:"又称竹笛，是中国传统吹管乐器中最具代表性的乐器之一。它历史悠久，音色清脆嘹亮、刚柔并济，既能表现江南的婉约，也能吹出塞北的豪情，因此常被称为“民乐之魂”。",history:"笛子的历史可追溯到约八九千年前的新石器时代，最早的雏形是骨笛。河南舞阳贾湖遗址出土的贾湖骨笛，是世界上最早的可吹奏乐器之一。黄帝时期传说开始用竹子制笛；秦汉时期竹笛形制已较成熟，出现七孔笛；唐代笛子进入鼎盛，宫廷与民间都极盛行；宋元以后广泛用于戏曲伴奏，并逐渐形成不同地域风格。",construction:"笛子通常由一根竹管制成，多用紫竹、苦竹等材料。管身开有吹孔、膜孔、按音孔和出音孔。膜孔上贴笛膜，笛膜振动是竹笛音色清脆明亮的关键。管内中空，两端常缠丝线、涂漆，以防开裂并作装饰。",schools:"近代笛子主要分南派和北派。南派以曲笛为主，流行于江浙、广东等地，风格清丽典雅、委婉细腻，代表演奏家有赵松庭、陆春龄。北派以梆笛为主，流行于山东、河北、山西等地，风格刚健豪爽、热烈奔放，代表演奏家有冯子存、刘管乐。",featuredMusic:"无羁（笛子版）",zones:[{key:"history",zone:"上",anchor:"吹孔端",x:.18,y:.5},{key:"construction",zone:"中",anchor:"管身 · 膜孔 · 按音孔",x:.5,y:.5},{key:"schools",zone:"下",anchor:"出音端 · 丝线缠漆",x:.82,y:.5}]},{slug:"xiao",code:"XIAO.005",name:"箫",nameEn:"XIAO",category:"吹管",line:"文人雅士之器",altName:"洞箫",image:"assets/xiao.png",music:"assets/audio/xiao.mp3",featuredMusic:"清平乐（箫）",imageAlt:"紫竹洞箫，管身铜箍、音孔与红色流苏",historyImg:"assets/xiao-bone.png",historyImgCaption:"新石器时代骨哨 · 箫之远祖",summary:"乐器 05 / 06 · 文人雅士之器",intro:"又称洞箫，是中国传统吹管乐器中最具文人气息的乐器之一。它历史悠久，音色柔雅深沉、幽静典雅，既能表现悠远空灵的意境，也能抒发细腻含蓄的情感，因此常被称为“文人雅士之器”。",history:"箫的历史可追溯到新石器时代的骨哨和骨笛，如浙江河姆渡出土的骨哨和河南舞阳的贾湖骨笛，距今已有七千至九千年的历史。虞舜时期创制竹制箫并用于《韶》乐，周代纳入“八音”分类。考古发现战国时期已有骨质排箫，汉代壁画中可见吹箫场景。魏晋至唐，竖吹乐器被称为“笛”，宋元时期定名“箫”，并衍生出燕乐箫、鼓吹箫等类型。明代起与横笛明确区分，清代形制与现代箫基本一致。历史上，箫在汉代称“篴”或“竖篴”，西晋乐工列和、中书监荀勖曾对箫进行改进。",construction:"箫通常由一根竹管制成，多用紫竹、白竹或黄枯竹等材料，全长约70至80厘米。管身上端利用天然竹节封口，边缘开有半椭圆形吹孔；管身开有六至八个按音孔，六孔箫为前五后一，八孔箫为前七后一，八孔箫是现代改进后的常见形制。箫不设膜孔，底端为开管，近尾端有出音孔。专业演奏用箫会增设铜插口以便调节音高，主要品种包括洞箫、琴箫、玉屏箫等。",schools:"箫在历史上更多是文人墨客抒发情感的消遣之物，专门独奏曲目极少，因此没有形成如笛子那般鲜明的风格流派。但在制作和演奏上，仍有南箫与北箫之别。南箫（如福建南音所用）管身较粗，张力大、声音沉厚；北箫（如琴箫）管身较细，音色典雅清幽。此外，流传于陕西西安高陵县的“高陵洞箫”是北派洞箫的代表。",zones:[{key:"history",zone:"上",anchor:"吹口端 · 竹节封口",x:.5,y:.14},{key:"construction",zone:"中",anchor:"管身 · 按音孔 · 铜插口",x:.5,y:.5},{key:"schools",zone:"下",anchor:"底端 · 出音孔 · 流苏",x:.5,y:.85}]},{slug:"bianzhong",code:"BIANZHONG.006",name:"编钟",nameEn:"BIANZHONG",category:"打击",line:"礼乐重器",altName:"青铜编钟",image:"assets/bianzhong.png",music:"assets/audio/bianzhong.mp3",featuredMusic:"禅钟·禅音",imageAlt:"编钟，双层钟架、悬挂青铜钟体与钟槌",historyImg:"assets/bianzhong-zeng.png",historyImgCaption:"曾侯乙墓出土编钟 · 65件 · 先秦礼乐最高成就",summary:"乐器 06 / 06 · 礼乐重器",intro:"又称青铜编钟，是中国古代最具代表性的打击乐器之一。它历史悠久，气势恢宏，音色浑厚悠远、庄严典雅，既能演奏旋律，也能烘托和声，常被称为“礼乐重器”和“古代世界第八大奇迹”。",history:"编钟最早出现于商朝，距今约三千五百年，由铜铃和铜铙演变而来。西周时期，编钟纳入礼乐制度，成为王公贵族身份等级的象征，多由三枚一组。春秋战国时期，编钟进入鼎盛，数量增至九枚或十三枚一组，工艺与音律达到高峰。秦汉以后，随着礼乐文化衰落，编钟制作逐渐式微。清代以后，编钟进入再研究与制作时期。1978年湖北随州曾侯乙墓出土的编钟，共65件，是迄今发现规模最大、保存最好、音律最全的一套，代表了中国先秦礼乐文明与青铜铸造技术的最高成就。",construction:"编钟由青铜铸成，钟体呈合瓦形，即扁圆形，如两片瓦片扣合，与寺庙中的圆形钟截然不同。钟体各部位有专名：舞部为钟顶平面，钲部为中部，篆部为钲部两侧的狭长区域，鼓部为下部敲击处，铣为两侧的棱。钟体表面常铸有精美的蟠螭纹、云雷纹等，并铸刻铭文。编钟按大小和音高次序悬挂于巨大的钟架上，钟架多为铜木结构，分为多层多面。曾侯乙编钟分三层八组，由六十五件钟组成，钟架长达七米以上。",schools:"编钟没有形成如笛子、古筝那样以演奏风格划分的流派，但不同地域的编钟在形制和装饰上各具特色。中原地区的编钟承袭周式传统，形制规整，纹饰典雅，代表西周礼乐的正统。南方楚、曾、蔡、吴、越等地的编钟则融入地方文化元素，如越式钟体扁而瘦长，甬短，饰有细线云雷纹、横S纹等；楚地编钟在编列上也有独特之处，常见十一件组和十三件组的组合。曾国编钟的音阶结构以宫、商、徵、羽为基本骨干，以徵为主音的低音音序排列与中原传统有较大区别，体现了南北文化的交融。",zones:[{key:"history",zone:"上",anchor:"上层钟 · 横梁",x:.5,y:.26},{key:"construction",zone:"中",anchor:"下层钟 · 合瓦钟体",x:.5,y:.55},{key:"schools",zone:"下",anchor:"钟架底座 · 钟槌",x:.5,y:.82}]}];